self.addEventListener('install',()=>self.skipWaiting());
self.addEventListener('activate',event=>event.waitUntil(self.clients.claim()));
function safeTarget(value){const url=new URL(self.registration.scope);if(typeof value==='string'&&/^#entregas\/[\w-]{1,180}$/.test(value))url.hash=value;return url.href;}
self.addEventListener('push',event=>{let data={};try{data=event.data?.json()||{};}catch{}event.waitUntil(self.registration.showNotification(data.title||'PitStop · Nueva venta',{body:data.body||'Hay una nueva venta para revisar en el panel.',icon:'./icon-192.png',badge:'./icon-192.png',tag:data.tag||'pitstop-sale',data:{url:safeTarget(data.url)},renotify:false}));});
self.addEventListener('notificationclick',event=>{event.notification.close();event.waitUntil((async()=>{const target=new URL(event.notification.data?.url||self.registration.scope);const url=safeTarget(target.hash);for(const client of await self.clients.matchAll({type:'window',includeUncontrolled:true}))if(client.url.startsWith(self.registration.scope)){await client.navigate(url);await client.focus();return;}await self.clients.openWindow(url);})());});
